package com.company.platform.order.api;
import com.company.platform.order.application.OrderService;import com.company.platform.order.domain.Order;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/orders") public class OrderController{private final OrderService service;public OrderController(OrderService s){service=s;}public record ItemRequest(UUID sellableProductId,String productSnapshot,int quantity,BigDecimal unitPrice){}public record CreateRequest(UUID customerId,UUID storeId,String currency,List<ItemRequest> items){}public record OrderResponse(UUID id,String orderNumber,UUID tenantId,UUID customerId,UUID storeId,String status,String currency,BigDecimal subtotal,List<?> items){}private OrderResponse dto(Order o){return new OrderResponse(o.id(),o.orderNumber().value(),o.tenantId(),o.customerId(),o.storeId(),o.status().name(),o.currency().getCurrencyCode(),o.subtotal().amount(),o.items());}
 @PostMapping @PreAuthorize("hasAuthority('ORDER_CREATE')")public OrderResponse create(@RequestBody CreateRequest r){var items=r.items().stream().map(i->new OrderService.ItemCommand(i.sellableProductId(),i.productSnapshot(),i.quantity(),i.unitPrice())).toList();return dto(service.create(r.customerId(),r.storeId(),Currency.getInstance(r.currency()),items));}
 @GetMapping("/{id}") @PreAuthorize("hasAuthority('ORDER_READ')")public OrderResponse get(@PathVariable UUID id){return dto(service.get(id));}@GetMapping("/customer/{id}") @PreAuthorize("hasAuthority('ORDER_READ')")public List<OrderResponse> customer(@PathVariable UUID id){return service.byCustomer(id).stream().map(this::dto).toList();}@GetMapping("/store/{id}") @PreAuthorize("hasAuthority('ORDER_READ')")public List<OrderResponse> store(@PathVariable UUID id){return service.byStore(id).stream().map(this::dto).toList();}@PostMapping("/{id}/confirm") @PreAuthorize("hasAuthority('ORDER_CONFIRM')")public OrderResponse confirm(@PathVariable UUID id){return dto(service.confirm(id));}@PostMapping("/{id}/cancel") @PreAuthorize("hasAuthority('ORDER_CANCEL')")public OrderResponse cancel(@PathVariable UUID id){return dto(service.cancel(id));}}
